    "cpp": "#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\ntemplate <typename T>\nT maxOf(const vector<T>& xs) {\n    T best = xs[0];\n    for (const T& x : xs) if (x > best) best = x;\n    return best;\n}\n\ntemplate <typename T>\nclass Stack {\n    vector<T> items;\npublic:\n    void push(const T& x) { items.push_back(x); }\n    T pop() { T x = items.back(); items.pop_back(); return x; }\n    size_t size() const { return items.size(); }\n};\n\nint main() {\n    cout << \"max of [3, 9, 4] = \" << maxOf(vector<int>{3, 9, 4}) << endl;\n    cout << \"max of [pear, apple, fig] = \" << maxOf(vector<string>{\"pear\", \"apple\", \"fig\"}) << endl;\n    Stack<string> s;\n    s.push(\"a\"); s.push(\"b\"); s.push(\"c\");\n    cout << \"stack pop: \" << s.pop() << endl;\n    cout << \"stack size: \" << s.size() << endl;\n}",
    "java": "import java.util.*;\n\npublic class Main {\n    static <T extends Comparable<T>> T maxOf(List<T> xs) {     // T must be comparable\n        T best = xs.get(0);\n        for (T x : xs) if (x.compareTo(best) > 0) best = x;\n        return best;\n    }\n\n    static class Stack<T> {\n        private final ArrayList<T> items = new ArrayList<>();\n        void push(T x) { items.add(x); }\n        T pop() { return items.remove(items.size() - 1); }\n        int size() { return items.size(); }\n    }\n\n    public static void main(String[] args) {\n        System.out.println(\"max of [3, 9, 4] = \" + maxOf(List.of(3, 9, 4)));\n        System.out.println(\"max of [pear, apple, fig] = \" + maxOf(List.of(\"pear\", \"apple\", \"fig\")));\n        Stack<String> s = new Stack<>();\n        s.push(\"a\"); s.push(\"b\"); s.push(\"c\");\n        System.out.println(\"stack pop: \" + s.pop());\n        System.out.println(\"stack size: \" + s.size());\n    }\n}",
    "python": "from typing import Generic, TypeVar\n\nT = TypeVar(\"T\")\n\ndef max_of(xs: list[T]) -> T:          # type hints document intent; Python does not enforce them\n    best = xs[0]\n    for x in xs:\n        if x > best:\n            best = x\n    return best\n\nclass Stack(Generic[T]):\n    def __init__(self) -> None:\n        self.items: list[T] = []\n    def push(self, x: T) -> None:\n        self.items.append(x)\n    def pop(self) -> T:\n        return self.items.pop()\n    def size(self) -> int:\n        return len(self.items)\n\nprint(\"max of [3, 9, 4] =\", max_of([3, 9, 4]))\nprint(\"max of [pear, apple, fig] =\", max_of([\"pear\", \"apple\", \"fig\"]))\ns: Stack[str] = Stack()\nfor c in \"abc\":\n    s.push(c)\nprint(\"stack pop:\", s.pop())\nprint(\"stack size:\", s.size())",
    "js": "function maxOf(xs) {                       // no generics needed: types are checked at run time\n  return xs.reduce((best, x) => (x > best ? x : best));\n}\n\nclass Stack {\n  #items = [];                             // # makes the field private\n  push(x) { this.#items.push(x); }\n  pop() { return this.#items.pop(); }\n  size() { return this.#items.length; }\n}\n\nconsole.log(\"max of [3, 9, 4] =\", maxOf([3, 9, 4]));\nconsole.log(\"max of [pear, apple, fig] =\", maxOf([\"pear\", \"apple\", \"fig\"]));\nconst s = new Stack();\nfor (const c of \"abc\") s.push(c);\nconsole.log(\"stack pop:\", s.pop());\nconsole.log(\"stack size:\", s.size());",
    "ts": "function maxOf<T>(xs: T[]): T {\n  return xs.reduce((best, x) => (x > best ? x : best));\n}\n\nclass Stack<T> {\n  #items: T[] = [];\n  push(x: T): void { this.#items.push(x); }\n  pop(): T | undefined { return this.#items.pop(); }\n  size(): number { return this.#items.length; }\n}\n\nconsole.log(\"max of [3, 9, 4] =\", maxOf([3, 9, 4]));\nconsole.log(\"max of [pear, apple, fig] =\", maxOf([\"pear\", \"apple\", \"fig\"]));\nconst s = new Stack<string>();\nfor (const c of \"abc\") s.push(c);\nconsole.log(\"stack pop:\", s.pop());\nconsole.log(\"stack size:\", s.size());",
    "rust": "fn max_of<T: PartialOrd + Copy>(xs: &[T]) -> T {    // trait bounds say what T must support\n    let mut best = xs[0];\n    for &x in xs { if x > best { best = x; } }\n    best\n}\n\nstruct Stack<T> { items: Vec<T> }\n\nimpl<T> Stack<T> {\n    fn new() -> Self { Stack { items: Vec::new() } }\n    fn push(&mut self, x: T) { self.items.push(x); }\n    fn pop(&mut self) -> Option<T> { self.items.pop() }\n    fn size(&self) -> usize { self.items.len() }\n}\n\nfn main() {\n    println!(\"max of [3, 9, 4] = {}\", max_of(&[3, 9, 4]));\n    println!(\"max of [pear, apple, fig] = {}\", max_of(&[\"pear\", \"apple\", \"fig\"]));\n    let mut s = Stack::new();\n    for c in [\"a\", \"b\", \"c\"] { s.push(c); }\n    println!(\"stack pop: {}\", s.pop().unwrap());\n    println!(\"stack size: {}\", s.size());\n}"
