    "js": "const users = new Map([[1, \"Asha\"], [2, \"Ben\"]]);\n\nconst findUser = (id) => users.get(id);    // undefined when missing\n\nfor (const id of [2, 9]) {\n  console.log(`user ${id}:`, findUser(id) ?? \"not found\");\n}\nconst nickname = null;\nconsole.log(\"nickname:\", nickname ?? \"guest\");   // ?? replaces only null and undefined, unlike ||",
    "ts": "const users = new Map<number, string>([[1, \"Asha\"], [2, \"Ben\"]]);\n\nconst findUser = (id: number): string | undefined => users.get(id);\n\nfor (const id of [2, 9]) {\n  console.log(`user ${id}:`, findUser(id) ?? \"not found\");\n}\nconst nickname: string | null = null;      // strictNullChecks makes you handle null before use\nconsole.log(\"nickname:\", nickname ?? \"guest\");",
