    "rust": "use std::collections::BTreeMap;\n\nfn main() {\n    let mut m: BTreeMap<&str, i32> = BTreeMap::from([(\"a\", 1), (\"b\", 2), (\"c\", 3), (\"d\", 4)]);\n    // for (k, v) in &m { if v % 2 == 0 { m.remove(k); } }   // does not compile: the loop borrows m\n    m.retain(|_, v| *v % 2 != 0);\n    let line: Vec<String> = m.iter().map(|(k, v)| format!(\"{}={}\", k, v)).collect();\n    println!(\"after removing even values: {}\", line.join(\" \"));\n}"
