  "custom-keys": {
    "cpp": "#include <functional>\n#include <iostream>\n#include <string>\n#include <unordered_map>\nusing namespace std;\n\nstruct Point {\n    int x, y;\n    bool operator==(const Point& o) const { return x == o.x && y == o.y; }\n};\n\nstruct PointHash {                       // unordered_map needs a hash function for its key type\n    size_t operator()(const Point& p) const { return hash<long long>()(((long long)p.x << 32) ^ (unsigned)p.y); }\n};\n\nint main() {\n    unordered_map<Point, string, PointHash> grid;\n    grid[{2, 3}] = \"treasure\";\n    cout << \"found (2, 3): \" << grid.at({2, 3}) << endl;\n    cout << \"has (3, 2): \" << boolalpha << (grid.count({3, 2}) > 0) << endl;\n}",
    "java": "import java.util.*;\n\npublic class Main {\n    record Point(int x, int y) {}                 // equals and hashCode compare the fields\n\n    static class RawPoint {                       // a plain class: equals and hashCode compare identity\n        final int x, y;\n        RawPoint(int x, int y) { this.x = x; this.y = y; }\n    }\n\n    public static void main(String[] args) {\n        Map<Point, String> grid = new HashMap<>();\n        grid.put(new Point(2, 3), \"treasure\");\n        System.out.println(\"found (2, 3): \" + grid.get(new Point(2, 3)));\n        System.out.println(\"has (3, 2): \" + grid.containsKey(new Point(3, 2)));\n\n        Map<RawPoint, String> raw = new HashMap<>();\n        raw.put(new RawPoint(2, 3), \"treasure\");\n        System.out.println(\"class without equals and hashCode: \" + raw.get(new RawPoint(2, 3)));\n    }\n}",
    "python": "from dataclasses import dataclass\n\n@dataclass(frozen=True)              # frozen: fields cannot change, so the object is hashable\nclass Point:\n    x: int\n    y: int\n\nclass RawPoint:                      # a plain class compares and hashes by identity\n    def __init__(self, x, y):\n        self.x, self.y = x, y\n\ngrid = {Point(2, 3): \"treasure\"}\nprint(\"found (2, 3):\", grid[Point(2, 3)])\nprint(\"has (3, 2):\", str(Point(3, 2) in grid).lower())\nraw = {RawPoint(2, 3): \"treasure\"}\nprint(\"class without __eq__ and __hash__:\", raw.get(RawPoint(2, 3)))",
    "js": "class Point {\n  constructor(x, y) { this.x = x; this.y = y; }\n  key() { return `${this.x},${this.y}`; }      // Map compares objects by identity: key by a string instead\n}\n\nconst grid = new Map([[new Point(2, 3).key(), \"treasure\"]]);\nconsole.log(\"found (2, 3):\", grid.get(new Point(2, 3).key()));\nconsole.log(\"has (3, 2):\", grid.has(new Point(3, 2).key()));\nconst raw = new Map([[new Point(2, 3), \"treasure\"]]);\nconsole.log(\"object as key:\", raw.get(new Point(2, 3)));",
    "ts": "class Point {\n  x: number;\n  y: number;\n  constructor(x: number, y: number) { this.x = x; this.y = y; }\n  key(): string { return `${this.x},${this.y}`; }\n}\n\nconst grid = new Map<string, string>([[new Point(2, 3).key(), \"treasure\"]]);\nconsole.log(\"found (2, 3):\", grid.get(new Point(2, 3).key()));\nconsole.log(\"has (3, 2):\", grid.has(new Point(3, 2).key()));\nconst raw = new Map<Point, string>([[new Point(2, 3), \"treasure\"]]);\nconsole.log(\"object as key:\", raw.get(new Point(2, 3)));",
    "rust": "use std::collections::HashMap;\n\n#[derive(Hash, PartialEq, Eq)]          // derive makes the struct usable as a key\nstruct Point { x: i32, y: i32 }\n\nfn main() {\n    let mut grid: HashMap<Point, &str> = HashMap::new();\n    grid.insert(Point { x: 2, y: 3 }, \"treasure\");\n    println!(\"found (2, 3): {}\", grid[&Point { x: 2, y: 3 }]);\n    println!(\"has (3, 2): {}\", grid.contains_key(&Point { x: 3, y: 2 }));\n}"
  }
